function renderCompactSelfCalendar(records){const month=currentMonth(),first=new Date(`${month}-01T12:00:00`),days=new Date(first.getFullYear(),first.getMonth()+1,0).getDate(),start=(first.getDay()+6)%7,byDate=Object.fromEntries(records.map(record=>[record.date,record]));let cells='';for(let index=0;index<start;index++)cells+='<td class="portal-calendar-empty"></td>';for(let day=1;day<=days;day++){const date=`${month}-${String(day).padStart(2,'0')}`,record=byDate[date],status=record?.status?.toLowerCase()||'empty';cells+=`<td class="portal-calendar-day ${status}" title="${record?esc(record.status):'No record'}"><span class="portal-calendar-date">${day}</span><span class="portal-calendar-status">${record?esc(record.status.slice(0,1)):'-'}</span></td>`}while(cells.split('</td>').length%7!==1)cells+='<td class="portal-calendar-empty"></td>';let rows='';for(let index=0;index<cells.split('</td>').length-1;index+=7)rows+=`<tr>${cells.split('</td>').slice(index,index+7).join('</td>')}</td></tr>`;document.getElementById('selfAttendanceCalendar').innerHTML=`<table class="portal-calendar"><thead><tr><th>Mon</th><th>Tue</th><th>Wed</th><th>Thu</th><th>Fri</th><th>Sat</th><th>Sun</th></tr></thead><tbody>${rows}</tbody></table>`}
function renderModernSelfCalendar(records){const month=selfCalendarMonth,statusFilter=document.getElementById('selfCalendarStatus')?.value||'',filteredRecords=records.filter(record=>!statusFilter||record.status===statusFilter),first=new Date(`${month}-01T12:00:00`),days=new Date(first.getFullYear(),first.getMonth()+1,0).getDate(),start=(first.getDay()+6)%7,byDate=Object.fromEntries(filteredRecords.map(record=>[record.date,record])),cells=[];for(let index=0;index<start;index++)cells.push(null);for(let day=1;day<=days;day++){const date=`${month}-${String(day).padStart(2,'0')}`;cells.push({date,day,record:byDate[date]})}while(cells.length%7)cells.push(null);const rows=[];for(let index=0;index<cells.length;index+=7)rows.push(cells.slice(index,index+7).map(cell=>{if(!cell)return '<td class="modern-calendar-blank"></td>';const status=cell.record?.status?.toLowerCase()||'empty',weekend=new Date(`${cell.date}T12:00:00`).getDay()%6===0;return `<td class="modern-calendar-day ${status} ${weekend?'modern-calendar-weekend':''} ${cell.date===todayISO()?'modern-calendar-today':''}" title="${cell.record?esc(cell.record.status):'No matching record'}"><div class="modern-calendar-date">${cell.day}</div><div class="modern-calendar-mark">${cell.record?esc(cell.record.status.slice(0,3)):'—'}</div></td>`}).join(''));document.getElementById('selfAttendanceCalendar').innerHTML=`<div class="modern-calendar-shell"><div class="modern-calendar-head"><div><strong>${first.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</strong><span>Attendance overview</span></div><div class="modern-calendar-legend"><span><i class="legend-present"></i>Present</span><span><i class="legend-late"></i>Late</span><span><i class="legend-empty"></i>No record</span></div></div><table class="modern-calendar"><thead><tr><th>MON</th><th>TUE</th><th>WED</th><th>THU</th><th>FRI</th><th>SAT</th><th>SUN</th></tr></thead><tbody>${rows.map(row=>`<tr>${row}</tr>`).join('')}</tbody></table></div>`}
