function shiftWorksOnDay(shift,dayIndex){const names=['mon','tue','wed','thu','fri','sat','sun'],tokens=(shift.days||'Mon-Fri').match(/Mon(?:day)?|Tue(?:sday)?|Wed(?:nesday)?|Thu(?:rsday)?|Fri(?:day)?|Sat(?:urday)?|Sun(?:day)?/gi)||[],indices=tokens.map(token=>names.findIndex(name=>name===token.slice(0,3).toLowerCase())).filter(index=>index>=0);if(!indices.length)return dayIndex<5;if(/[-–]/.test(shift.days||'')&&indices.length>=2){const start=indices[0],end=indices[indices.length-1];return start<=end?dayIndex>=start&&dayIndex<=end:dayIndex>=start||dayIndex<=end}return indices.includes(dayIndex)}
