function parseCsv(text){const rows=[];let row=[],field='',quoted=false;for(let index=0;index<text.length;index++){const char=text[index];if(char==='"'){if(quoted&&text[index+1]==='"'){field+='"';index++}else quoted=!quoted}else if(char===','&&!quoted){row.push(field.trim());field=''}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&text[index+1]==='\n')index++;row.push(field.trim());if(row.some(value=>value!==''))rows.push(row);row=[];field=''}else field+=char}row.push(field.trim());if(row.some(value=>value!==''))rows.push(row);return rows}
function importEmployees(event){const file=event.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{const rows=parseCsv(String(reader.result).replace(/^\uFEFF/,''));if(rows.length<2){toast('CSV must include a header and at least one employee');event.target.value='';return}const headers=rows.shift().map(value=>value.toLowerCase().replace(/[\s-]+/g,'_')),required=['id','name'];if(required.some(header=>!headers.includes(header))){toast('CSV headers must include id and name');event.target.value='';return}let added=0,duplicates=0,invalid=0;rows.forEach(values=>{const row=Object.fromEntries(headers.map((header,index)=>[header,values[index]||''])),id=row.id.trim(),name=row.name.trim();if(!id||!name){invalid++;return}if(db.employees.some(employee=>employee.id.toLowerCase()===id.toLowerCase())){duplicates++;return}const dept=row.department||row.dept||'General',number=value=>Number.isFinite(Number(value))?Number(value):0,employee={id,name,dept,shift:row.shift||'',email:row.email||'',location:row.location||'Main Office',phone:row.phone||'',rate:number(row.rate),status:row.status||'Active',bio:'Not enrolled',workingHours:number(row.working_hours||row.workinghours)||8,startTime:row.start_time||row.starttime||'09:00',endTime:row.end_time||row.endtime||'17:00',basicSalary:number(row.basic_salary||row.basicsalary),allowance:number(row.allowance),monthlySalary:number(row.monthly_salary||row.monthlysalary),monthlyBonus:number(row.monthly_bonus||row.monthlybonus),monthlyDeduction:number(row.monthly_deduction||row.monthlydeduction)};if(!db.departments.includes(dept))db.departments.push(dept);db.employees.push(employee);db.leaveBalances[id]={Annual:20,Sick:10,Personal:5};added++});if(added){addAudit('Employees imported',`${added} employee${added===1?'':'s'}`);save();renderAll()}toast(`${added} imported · ${duplicates} duplicate · ${invalid} invalid`);event.target.value=''};reader.readAsText(file)}
function openPayslip(){const employee=getSelectedSelfEmployee();if(!employee)return;const summary=getEmployeeMonthlySummary(employee,currentMonth());const salary=summary.salary;document.getElementById('payslipContent').innerHTML=`<div class="payslip"><div class="payslip-head"><div><b>${esc(employee.name)}</b><small>${esc(employee.id)} · ${esc(employee.dept)}</small></div><b>${esc(currentMonth())}</b></div><div class="payslip-line"><span>Basic salary</span><b>${money(salary.basic)}</b></div><div class="payslip-line"><span>Allowance</span><b>${money(salary.allowance)}</b></div><div class="payslip-line"><span>Paid leave salary</span><b>${money(summary.leave.paidLeaveSalary)}</b></div><div class="payslip-line"><span>Unpaid leave deduction</span><b>-${money(summary.leave.unpaidDeduction)}</b></div><div class="payslip-line"><span>Overtime</span><b>${money(summary.totalOTPay)}</b></div><div class="payslip-line"><span>Bonus / deduction</span><b>${money(summary.bonus-summary.deduction)}</b></div><div class="payslip-total"><span>Net pay</span><b>${money(summary.totalPay)}</b></div></div>`;openModal('payslipModal')}
