function finalizePayroll(){const period=db.manager.payrollPeriods[currentMonth()]||{status:'Open'};if(period.status==='Finalized'){toast('Payroll is already finalized');return}if(period.status!=='Locked'){toast('Lock the payroll period from Manager Center before finalizing');return}period.status='Finalized';db.manager.payrollPeriods[currentMonth()]=period;addAudit('Payroll finalized',currentMonth());save();renderAll();toast('Payroll finalized')}
function decideException(id,status){
 if(!canPerform(['admin','manager']))return;
 const item=db.manager.exceptionRequests.find(x=>x.id===id);if(!item)return;
 const comment=prompt(`${status} comment (optional):`);if(comment===null)return;item.status=status;item.comment=comment.trim();item.managerNote=`Reviewed by ${currentRole}`;item.decidedBy=currentRole;item.decidedAt=new Date().toISOString();addAudit(`Exception ${status.toLowerCase()}`,`${emp(item.emp)?.name||item.emp} — ${item.type}`);db.manager.notifications.push({id:`NT-${Date.now()}`,emp:item.emp,title:`Exception ${status.toLowerCase()}`,body:`${emp(item.emp)?.name||item.emp} · ${item.type}`,time:nowLabel(),read:false});save();renderAll();toast(`Attendance exception ${status.toLowerCase()}`)
}
function decideOvertime(id,status){
 if(!canPerform(['admin','manager']))return;
 const item=db.manager.overtimeRequests.find(x=>x.id===id);if(!item)return;const comment=prompt(`${status} comment (optional):`);if(comment===null)return;
 item.status=status;item.comment=comment.trim();item.managerNote=`Reviewed by ${currentRole}`;item.decidedBy=currentRole;item.decidedAt=new Date().toISOString();addAudit(`Overtime ${status.toLowerCase()}`,`${emp(item.emp)?.name||item.emp} — ${item.hours} hours`);db.manager.notifications.push({id:`NT-${Date.now()}`,emp:item.emp,title:`Overtime ${status.toLowerCase()}`,body:`${emp(item.emp)?.name||item.emp} · ${item.hours} hours`,time:nowLabel(),read:false});save();renderAll();toast(`Overtime ${status.toLowerCase()}`)
}
function togglePayrollLock(){
 if(!canPerform(['admin','manager','payroll']))return;
 const period=db.manager.payrollPeriods[currentMonth()]||{status:'Open'};if(period.status==='Finalized'){toast('Finalized payroll cannot be unlocked');return}period.status=period.status==='Locked'?'Open':'Locked';db.manager.payrollPeriods[currentMonth()]=period;addAudit(`Payroll ${period.status.toLowerCase()}`,currentMonth());save();renderAll();toast(`Payroll ${period.status.toLowerCase()}`)
}
function markNotificationsRead(){db.manager.notifications.forEach(x=>x.read=true);save();renderAll();toast('Notifications marked as read')}
async function employeeClockAction(action){const employee=getSelectedSelfEmployee();if(!employee){toast('Select an employee first');return}const date=todayISO(),record=db.attendance.find(item=>item.emp===employee.id&&item.date===date);if(action==='in'&&record){toast('Today already has an attendance record');return}if(action==='out'&&!record){toast('Clock in before clocking out');return}if(action==='out'&&record.out){toast('Today is already checked out');return}try{const place=await resolveAttendancePlace(),time=new Date().toTimeString().slice(0,5);if(action==='in'){db.attendance.push({date,emp:employee.id,method:'Portal',in:time,out:'',location:place.name,gps:place.gps,status:'Present'});db.manager.notifications.push({id:`NT-${Date.now()}`,emp:employee.id,title:'Clock-in recorded',body:`Your portal clock-in was recorded at ${formatTime(time)}.`,time:nowLabel(),read:false});addAudit('Portal clock-in',employee.name)}else{record.out=time;record.outGps=place.gps;if(place.name!=='GPS recorded')record.location=place.name;db.manager.notifications.push({id:`NT-${Date.now()}`,emp:employee.id,title:'Clock-out recorded',body:`Your portal clock-out was recorded at ${formatTime(time)}.`,time:nowLabel(),read:false});addAudit('Portal clock-out',employee.name)}save();renderAll();toast(action==='in'?'Clock-in recorded':'Clock-out recorded')}catch(error){toast(error.message||'Could not validate attendance location')}}
function markSelfNotificationsRead(){const employee=getSelectedSelfEmployee();if(!employee)return;db.manager.notifications.filter(item=>!item.emp||item.emp===employee.id).forEach(item=>item.read=true);save();renderAll();toast('Portal messages marked as read')}
