 const rows=db.attendance.map((record,index)=>({record,index})).filter(({record:a})=>{const recordDate=new Date(`${a.date}T12:00:00`);let inPeriod=true;if(preset!=='all'&&period==='day')inPeriod=matchesDatePreset(a.date,preset,from,to);if(preset!=='all'&&period==='week'){const anchor=new Date(`${datePresetRange(preset,from,to).from}T12:00:00`);const diff=Math.floor((recordDate-anchor)/86400000);inPeriod=diff>=0&&diff<7}if(preset!=='all'&&period==='month')inPeriod=a.date.startsWith((datePresetRange(preset,from,to).from||from).slice(0,7));return inPeriod&&(!q||(emp(a.emp)?.name||'').toLowerCase().includes(q)||a.emp.toLowerCase().includes(q))&&(!status||a.status===status)});
