function getGpsPosition(){return new Promise((resolve,reject)=>{if(!navigator.geolocation){reject(new Error('This browser does not support location capture'));return}navigator.geolocation.getCurrentPosition(resolve,()=>reject(new Error('Location permission is required for attendance')), {enableHighAccuracy:true,timeout:12000,maximumAge:30000})})}
function distanceInMeters(latitudeA,longitudeA,latitudeB,longitudeB){const radians=value=>value*Math.PI/180,deltaLatitude=radians(latitudeB-latitudeA),deltaLongitude=radians(longitudeB-longitudeA),a=Math.sin(deltaLatitude/2)**2+Math.cos(radians(latitudeA))*Math.cos(radians(latitudeB))*Math.sin(deltaLongitude/2)**2;return 6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))}
async function resolveAttendancePlace(locationName=''){
 const requested=db.locations.find(location=>location.name===locationName&&location.status!=='Inactive'),geofences=db.locations.filter(location=>location.status!=='Inactive'&&Number.isFinite(Number(location.lat))&&location.lat!==''&&Number.isFinite(Number(location.lng))&&location.lng!==''),hasGeofences=geofences.length>0;
 if(locationName&&!requested)throw new Error('Selected attendance location is not active');
 if(!db.settings.requireLocation)return {name:requested?.name||locationName||'Unspecified',gps:null};
 const position=await getGpsPosition(),gps={latitude:position.coords.latitude,longitude:position.coords.longitude,accuracy:position.coords.accuracy};
 if(requested?.lat&&requested?.lng){const distance=distanceInMeters(gps.latitude,gps.longitude,Number(requested.lat),Number(requested.lng));if(distance>Number(requested.radius||150))throw new Error(`Outside the ${requested.name} geofence (${Math.round(distance)}m away)`)}
 else if(!requested&&hasGeofences){const nearest=geofences.map(location=>({location,distance:distanceInMeters(gps.latitude,gps.longitude,Number(location.lat),Number(location.lng))})).sort((left,right)=>left.distance-right.distance)[0];if(nearest.distance>Number(nearest.location.radius||150))throw new Error('You are outside all active attendance geofences');return {name:nearest.location.name,gps}}
 else if(requested&&!requested.lat&&hasGeofences)throw new Error('This location has no geofence coordinates configured');
 return {name:requested?.name||locationName||'GPS recorded',gps};
}
function openAttendanceEditor(index=-1){editingAttendance=index;fillSelects();const form=document.querySelector('#attendanceModal form');form.reset();const record=db.attendance[index];document.getElementById('attendanceModalTitle').textContent=record?'Edit Attendance Record':'Manual Attendance Entry';document.getElementById('aDate').value=record?.date||todayISO();if(record){document.getElementById('aEmp').value=record.emp;document.getElementById('aIn').value=record.in||'';document.getElementById('aOut').value=record.out||'';document.getElementById('aMethod').value=record.method||'Manual';document.getElementById('aLocation').value=record.location||'';document.getElementById('aStatus').value=record.status||'Present'}openModal('attendanceModal')}
