function addDepartment(event){event.preventDefault();const name=document.getElementById('dName').value.trim(),previousName=editingDepartment,managerId=document.getElementById('dManager').value,costCenter=document.getElementById('dCostCenter').value.trim(),overtimeMultiplier=clampOvertimeMultiplier(document.getElementById('dOTMultiplier').value);if(!name){toast('Department name is required');return}if(db.departments.some(item=>item.toLowerCase()===name.toLowerCase()&&item!==previousName)){toast('A department with this name already exists');return}if(previousName&&previousName!==name){db.departments=db.departments.map(item=>item===previousName?name:item);db.employees.forEach(employee=>{if(employee.dept===previousName)employee.dept=name});db.departmentSettings[name]=db.departmentSettings[previousName]||{};delete db.departmentSettings[previousName]}else if(!previousName)db.departments.push(name);db.departmentSettings[name]={managerId,costCenter,overtimeMultiplier};addAudit(previousName?'Department updated':'Department added',name);save();closeModal('departmentModal');event.target.reset();editingDepartment=null;renderAll();toast('Department saved')}
