function decideLeave(index,status){if(!canPerform(['admin','manager']))return;const item=db.leaves[index];if(!item||item.status!=='Pending')return;const comment=prompt(`${status} comment (optional):`);if(comment===null)return;item.status=status;item.comment=comment.trim();item.managerNote=`Reviewed by ${currentRole}`;item.decidedBy=currentRole;item.decidedAt=new Date().toISOString();addAudit(`Leave ${status.toLowerCase()}`,emp(item.emp)?.name||item.emp);db.manager.notifications.push({id:`NT-${Date.now()}`,emp:item.emp,title:`Leave request ${status.toLowerCase()}`,body:`${item.type} leave from ${item.from} to ${item.to} was ${status.toLowerCase()}.`,time:nowLabel(),read:false});save();renderAll();toast(`Leave ${status.toLowerCase()}`)}
