function deleteSavedReportView(){const name=document.getElementById('reportSavedView').value;if(!name){toast('Select a saved view first');return}if(!confirm(`Delete saved report view "${name}"?`))return;db.savedReports=db.savedReports.filter(view=>view.name!==name);addAudit('Report view deleted',name);save();renderSavedReportViews();toast('Report view deleted')}
function clearReportFilters(){document.getElementById('reportSearch').value='';document.getElementById('reportFrom').value='';document.getElementById('reportTo').value='';document.getElementById('reportDept').value='';document.getElementById('reportStatus').value='';document.getElementById('reportSavedView').value='';renderReports()}
function downloadReport(){const rows=getReportRows(),data=[['Date','Employee','Department','Status','Hours','Pay','Location'],...rows.map(record=>[record.date,emp(record.emp)?.name||record.emp,emp(record.emp)?.dept||'',record.status,hours(record).toFixed(2),pay(record).toFixed(2),record.location||''])];const blob=new Blob([data.map(row=>row.map(value=>`"${String(value).replace(/"/g,'""')}"`).join(',')).join('\n')],{type:'text/csv'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`attendance-report-${todayISO()}.csv`;link.click();URL.revokeObjectURL(url)}
function printTable(id){let el=document.getElementById(id);if(!el){toast('Table not available');return}let w=window.open('','_blank');w.document.write(`<html><head><title>SmartAttend Report</title><style>body{font-family:Arial;padding:25px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:8px;text-align:left;font-size:11px}th{background:#f4f4f4}h2{margin-bottom:15px}</style></head><body><h2>SmartAttend Report</h2>${el.outerHTML}<script>window.print();<\/script></body></html>`);w.document.close()}
async function openScannerCamera(facingMode){const video=document.getElementById('scannerVideo');stopCamera();const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:facingMode}},audio:false});video.srcObject=stream;video.style.display='block';document.getElementById('cameraPlaceholder').hidden=true;await video.play();return video}
async function startQR(){
 const video=document.getElementById('scannerVideo'),res=document.getElementById('scanResult');
 if(!document.getElementById('setQR').checked){showScannerMessage('QR attendance is disabled in Settings.','error');return}
 stopAutomaticFaceRecognition();
 try{await openScannerCamera('environment');
 if('BarcodeDetector' in window){const detector=new BarcodeDetector({formats:['qr_code']});res.style.display='block';res.textContent='Camera active — point it at an employee QR code.';const loop=async()=>{if(video.style.display==='none')return;try{const codes=await detector.detect(video);if(codes.length){let val=codes[0].rawValue;recordScan('QR',val);stopCamera();return}}catch{}requestAnimationFrame(loop)};loop()}else{res.style.display='block';res.textContent='Camera active. This browser does not expose BarcodeDetector; enter the QR employee ID using the prompt.';let id=prompt('Enter employee ID encoded in the QR code (e.g. EMP-001):');if(id){recordScan('QR',id);stopCamera()}}}catch(err){showScannerMessage('Camera permission is unavailable or denied.','error')}
}
function getEnrolledEmployees(){return db.employees.filter(employee=>employee.status==='Active'&&employee.faceConsentAt&&Array.isArray(employee.faceDescriptor)&&employee.faceDescriptor.length===128)}
function matchFaceDescriptor(descriptor){const candidates=getEnrolledEmployees().map(employee=>({employee,distance:Math.sqrt(employee.faceDescriptor.reduce((sum,value,index)=>sum+(value-descriptor[index])**2,0))})).sort((left,right)=>left.distance-right.distance);if(!candidates.length)return {status:'unenrolled'};if(candidates[0].distance>0.45)return {status:'unmatched'};if(candidates[1]&&candidates[1].distance-candidates[0].distance<0.06)return {status:'ambiguous'};return {status:'matched',employee:candidates[0].employee}}
function stopAutomaticFaceRecognition(){faceScanActive=false;faceScanToken++;if(faceScanTimer)clearTimeout(faceScanTimer);faceScanTimer=0;stopCamera()}
async function runAutomaticFaceRecognition(token){if(!faceScanActive||token!==faceScanToken)return;const video=document.getElementById('scannerVideo'),result=document.getElementById('scanResult');try{if(video.readyState>=2){const faces=await faceapi.detectAllFaces(video,new faceapi.TinyFaceDetectorOptions({inputSize:320,scoreThreshold:0.6})).withFaceLandmarks(true).withFaceDescriptors();if(faces.length>1)result.textContent='Only one person should be in view.';else if(faces.length===1){const match=matchFaceDescriptor(faces[0].descriptor);if(match.status==='unenrolled')result.textContent='No employee face profiles are enrolled yet.';else if(match.status==='ambiguous')result.textContent='Face match is ambiguous. Use employee ID sign-in.';else if(match.status==='unmatched')result.textContent='Face not recognized. Use employee ID sign-in.';else if(Date.now()-lastFaceAttempt>8000){lastFaceAttempt=Date.now();const record=db.attendance.find(item=>item.emp===match.employee.id&&item.date===todayISO());if(!record)await completeEmployeeSignIn(match.employee,'Face recognition');else if(!record.out)await completeEmployeeSignOut(match.employee,record,'Face recognition');else{showEmployeeRecognition(match.employee,'out',record);stopAutomaticFaceRecognition()}if(!faceScanActive||token!==faceScanToken)return}}else result.textContent='Looking for an enrolled face…'}}catch(error){if(faceScanActive&&token===faceScanToken)showScannerMessage('Face recognition could not analyze this camera frame.','error')}if(faceScanActive&&token===faceScanToken)faceScanTimer=setTimeout(()=>runAutomaticFaceRecognition(token),400)}
async function startAutomaticFaceRecognition(){if(faceScanActive)return;const result=document.getElementById('scanResult');result.style.display='block';if(!db.settings.allowBiometric){showScannerMessage('Biometric sign-in is disabled in Settings.','error');return}faceScanActive=true;const token=++faceScanToken;result.textContent='Loading face recognition…';result.className='scan-result state-info';try{await ensureFaceModels();if(!faceScanActive||token!==faceScanToken)return;await openScannerCamera('user');if(!faceScanActive||token!==faceScanToken)return;result.textContent=getEnrolledEmployees().length?'Looking for an enrolled face…':'No employee face profiles are enrolled yet.';runAutomaticFaceRecognition(token)}catch(error){if(token===faceScanToken){faceScanActive=false;showScannerMessage(error.message||'Face recognition or camera is unavailable.','error')}}}
function derSignatureToRaw(signature){const bytes=new Uint8Array(signature);if(bytes.length===64)return bytes;if(bytes[0]!==0x30)throw new Error('Invalid device signature');let position=2;if(bytes[1]&0x80)position=2+(bytes[1]&0x7f);if(bytes[position++]!==0x02)throw new Error('Invalid device signature');const rLength=bytes[position++],r=bytes.slice(position,position+rLength);position+=rLength;if(bytes[position++]!==0x02)throw new Error('Invalid device signature');const sLength=bytes[position++],s=bytes.slice(position,position+sLength);const normalize=integer=>{let value=integer;while(value.length>32&&value[0]===0)value=value.slice(1);if(value.length>32)throw new Error('Invalid device signature');const result=new Uint8Array(32);result.set(value,32-value.length);return result},raw=new Uint8Array(64);raw.set(normalize(r),0);raw.set(normalize(s),32);return raw}
async function verifyEmployeeBiometric(employee,challenge,assertion){const credential=employee.biometricCredential;if(!credential)throw new Error('No device fingerprint is registered for this employee');if(encodeBase64Url(assertion.rawId)!==credential.id)throw new Error('The device returned an unexpected credential');if(!assertion.response.userHandle||encodeBase64Url(assertion.response.userHandle)!==credential.userId)throw new Error('The device did not identify the enrolled employee');const clientDataBytes=new Uint8Array(assertion.response.clientDataJSON),clientData=JSON.parse(new TextDecoder().decode(clientDataBytes));if(clientData.type!=='webauthn.get'||clientData.challenge!==encodeBase64Url(challenge)||clientData.origin!==location.origin||clientData.crossOrigin===true)throw new Error('Device verification context was invalid');const authenticatorData=new Uint8Array(assertion.response.getAuthenticatorData());if(authenticatorData.length<37||(authenticatorData[32]&0x05)!==0x05)throw new Error('Device user verification was not confirmed');const rpIdHash=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(location.hostname)));if(!rpIdHash.every((value,index)=>value===authenticatorData[index]))throw new Error('Device was verified for a different site');const counter=getWebAuthnCounter(authenticatorData);if(counter>0&&counter<=Number(credential.counter||0))throw new Error('This device credential has already been used or was reset');const publicKey=await crypto.subtle.importKey('spki',decodeBase64Url(credential.publicKey),{name:'ECDSA',namedCurve:'P-256'},false,['verify']),clientHash=new Uint8Array(await crypto.subtle.digest('SHA-256',clientDataBytes)),signedData=new Uint8Array(authenticatorData.length+clientHash.length);signedData.set(authenticatorData);signedData.set(clientHash,authenticatorData.length);const valid=await crypto.subtle.verify({name:'ECDSA',hash:'SHA-256'},publicKey,derSignatureToRaw(assertion.response.signature),signedData);if(!valid)throw new Error('Device signature could not be verified');credential.counter=counter;return true}
async function completeEmployeeSignOut(employee,record,method){try{const place=await resolveAttendancePlace(),signedAt=new Date();record.out=signedAt.toTimeString().slice(0,5);record.checkOutAt=signedAt.toISOString();record.outGps=place.gps;if(place.name&&place.name!=='Unspecified'&&place.name!=='GPS recorded')record.location=place.name;db.manager.notifications.push({id:`NT-${Date.now()}`,emp:employee.id,title:'Clock-out recorded',body:`Your ${method} clock-out was recorded at ${formatTime(record.out)}.`,time:signedAt.toLocaleString(),read:false});addAudit(`${method} clock-out`,employee.name);save();stopAutomaticFaceRecognition();renderAll();showEmployeeRecognition(employee,'out',record);return true}catch(error){showScannerMessage(error.message||'Could not validate attendance location.','error');return false}}
async function startFingerprint(){if(!db.settings.allowBiometric){showScannerMessage('Biometric attendance is disabled.','error');return}stopAutomaticFaceRecognition();if(!window.PublicKeyCredential||!window.isSecureContext){showScannerMessage('Device biometrics require WebAuthn support on localhost or HTTPS.','error');return}try{const challenge=crypto.getRandomValues(new Uint8Array(32)),assertion=await navigator.credentials.get({publicKey:{challenge,rpId:location.hostname,userVerification:'required',timeout:60000}});if(!assertion)throw new Error('Device verification was cancelled');const credentialId=encodeBase64Url(assertion.rawId),userHandle=assertion.response.userHandle?encodeBase64Url(assertion.response.userHandle):'',employee=db.employees.find(item=>item.biometricCredential&&(item.biometricCredential.id===credentialId||Boolean(userHandle&&item.biometricCredential.userId===userHandle)));if(!employee)throw new Error('No employee matched this device fingerprint. Register a discoverable credential first.');if(employee.status!=='Active')throw new Error('This employee is inactive');await verifyEmployeeBiometric(employee,challenge,assertion);const record=db.attendance.find(item=>item.emp===employee.id&&item.date===todayISO());if(!record)await completeEmployeeSignIn(employee,'Device biometric');else if(!record.out)await completeEmployeeSignOut(employee,record,'Device biometric');else showEmployeeRecognition(employee,'out',record);document.getElementById('scannerEmployeeId').value='';save()}catch(error){showScannerMessage(error.message||'Device fingerprint verification failed.','error')}}
async function recordScan(method,id){const employee=emp(id.trim());if(!employee){showScannerMessage('Employee ID not found.','error');return}if(method==='QR'&&!db.settings.allowQR){showScannerMessage('QR attendance is disabled in Settings.','error');return}if(employee.status!=='Active'){showScannerMessage('This employee is inactive.','error');return}const record=db.attendance.find(item=>item.emp===employee.id&&item.date===todayISO());if(record?.out){showEmployeeRecognition(employee,'out',record);stopCamera();return}if(record)await completeEmployeeSignOut(employee,record,'QR scan');else await completeEmployeeSignIn(employee,'QR scan');stopCamera()}
function appendScannerKey(value){const input=document.getElementById('scannerEmployeeId');input.value+=value;input.focus()}
function removeScannerKey(){const input=document.getElementById('scannerEmployeeId');input.value=input.value.slice(0,-1);input.focus()}
function clearScannerKeypad(){const input=document.getElementById('scannerEmployeeId');input.value='';input.focus()}
function resolveScannerEmployee(identifier){const value=identifier.trim().toLowerCase(),exact=db.employees.find(employee=>employee.id.toLowerCase()===value);if(exact)return {employee:exact,ambiguous:false};const digits=value.replace(/\D/g,'').replace(/^0+(?=\d)/,'');if(!digits)return {employee:null,ambiguous:false};const matches=db.employees.filter(employee=>employee.id.replace(/\D/g,'').replace(/^0+(?=\d)/,'')===digits);return {employee:matches.length===1?matches[0]:null,ambiguous:matches.length>1}}
function showScannerMessage(message,state='info'){const recognition=document.getElementById('scannerRecognition'),result=document.getElementById('scanResult');recognition.hidden=true;result.textContent=message;result.className=`scan-result state-${state}`;result.style.display='block'}
function showRecognitionFallback(employee){const photoContainer=document.getElementById('recognitionPhoto');photoContainer.replaceChildren();const initials=document.createElement('span');initials.textContent=employee.name.split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase();photoContainer.append(initials)}
function formatPunchDateTime(date,time){if(!date||!time)return '—';const displayDate=new Date(`${date}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric'});return `${displayDate} · ${formatTime(time)}`}
function showEmployeeRecognition(employee,action,record){const panel=document.getElementById('scannerRecognition'),photoContainer=document.getElementById('recognitionPhoto'),isClockOut=action==='out';document.getElementById('scanResult').style.display='none';photoContainer.replaceChildren();if(employee.photo){const image=document.createElement('img');image.src=employee.photo;image.alt=`${employee.name} employee photo`;image.onerror=()=>showRecognitionFallback(employee);photoContainer.append(image)}else showRecognitionFallback(employee);document.getElementById('recognitionTitle').textContent=isClockOut?'Clocked out':'Clocked in';document.getElementById('recognitionMessage').textContent=`Attendance recorded for ${employee.name}.`;document.getElementById('recognitionDate').textContent=new Date(`${record.date}T12:00:00`).toLocaleDateString(undefined,{weekday:'long',year:'numeric',month:'long',day:'numeric'});document.getElementById('recognitionTime').textContent=`${isClockOut?'Clock-out':'Clock-in'} · ${formatTime(isClockOut?record.out:record.in)}`;document.getElementById('recognitionCheckIn').textContent=formatPunchDateTime(record.date,record.in);document.getElementById('recognitionCheckOut').textContent=record.out?formatPunchDateTime(record.date,record.out):'Awaiting clock-out';panel.hidden=false}
async function completeEmployeeSignIn(employee,method){document.getElementById('scannerRecognition').hidden=true;if(employee.status!=='Active'){showScannerMessage('This employee is inactive.','error');return false}if(db.attendance.some(record=>record.emp===employee.id&&record.date===todayISO())){showScannerMessage('Today already has an attendance record.','error');return false}try{const place=await resolveAttendancePlace(),signedAt=new Date(),time=signedAt.toTimeString().slice(0,5),record={date:todayISO(),emp:employee.id,method,in:time,out:'',checkInAt:signedAt.toISOString(),location:place.name,gps:place.gps,status:'Present'};db.attendance.push(record);db.manager.notifications.push({id:`NT-${Date.now()}`,emp:employee.id,title:'Clock-in recorded',body:`Your ${method} sign-in was recorded at ${formatTime(time)}.`,time:signedAt.toLocaleString(),read:false});addAudit(`${method} sign-in`,employee.name);save();stopAutomaticFaceRecognition();renderAll();showEmployeeRecognition(employee,'in',record);return true}catch(error){showScannerMessage(error.message||'Could not validate attendance location.','error');return false}}
async function signInWithEmployeeId(event){event.preventDefault();stopAutomaticFaceRecognition();const input=document.getElementById('scannerEmployeeId'),{employee,ambiguous}=resolveScannerEmployee(input.value);if(ambiguous){showScannerMessage('More than one employee matches. Enter the full employee ID.','error');return}if(!employee){showScannerMessage('Employee ID not found.','error');return}const record=db.attendance.find(item=>item.emp===employee.id&&item.date===todayISO());if(record?.out){showEmployeeRecognition(employee,'out',record);input.value='';return}if(await (record?completeEmployeeSignOut(employee,record,'Employee ID'):completeEmployeeSignIn(employee,'Employee ID')))input.value=''}
function stopCamera(){const video=document.getElementById('scannerVideo');if(video.srcObject)video.srcObject.getTracks().forEach(track=>track.stop());video.srcObject=null;video.style.display='none';const placeholder=document.getElementById('cameraPlaceholder');if(placeholder)placeholder.hidden=false}
function saveSettings(){if(!canPerform(['admin']))return;
 db.settings.currency=document.getElementById('currency').value;
 db.settings.timeMode=document.getElementById('timeMode').value==='24'?'24':'12';
 db.settings.workingDays=Math.max(1,Math.min(7,Number(document.getElementById('workingDays').value)||5));
 db.settings.annualLeaveDays=Math.max(0,Math.min(60,Number(document.getElementById('annualLeaveDays').value)||0));
 db.settings.requireLocation=document.getElementById('setLocation').checked;
 db.settings.allowQR=document.getElementById('setQR').checked;
 db.settings.allowBiometric=document.getElementById('setBio').checked;
 save();renderAll();toast('Settings saved')
}
function updateConnectionStatus(){const banner=document.getElementById('connectionBanner');if(!banner)return;banner.textContent=navigator.onLine?'':'You are offline. Changes are stored locally and will sync when connected.';banner.classList.toggle('visible',!navigator.onLine)}
window.addEventListener('online',updateConnectionStatus);window.addEventListener('offline',updateConnectionStatus);
